```csharp
public abstract class BaseButtonGroupWindow : Window
{
    [Inject]
    protected IPublisher Publisher { get; set; }

    [Inject]
    protected IPublisher MessagePublisher { get; set; }

    protected abstract void InitializeButtons();

    protected override void OnShow()
    {
        InitializeButtons();

        // Общая логика для всех кнопок
        restartSessionButton.onClick.AddListener(RestartSession);
        exitMainMenuButton.onClick.AddListener(ExitMainMenu);
        exitStopMenuButton.onClick.AddListener(ExitStopMenu);
    }

    protected override void OnHide()
    {
        restartSessionButton.onClick.RemoveAllListeners();
        exitMainMenuButton.onClick.RemoveAllListeners();
        exitStopMenuButton.onClick.RemoveAllListeners();
    }

    private void RestartSession()
    {
        Publisher.Publish(new StartSessionMessage());
        Publisher.Publish(new EscapeWindowShowMessage());
    }

    private void ExitMainMenu()
    {
        MessagePublisher.Publish(new ExitFromSessionMessage());
    }

    private void ExitStopMenu()
    {
        MessagePublisher.Publish(new ExitStopMenuMessage());
    }
}
```

> 💡 **Примечание:** В данном примере предполагается, что у всех кнопок есть `restartSessionButton`, `exitMainMenuButton`, и `exitStopMenuButton`. Если в некоторых классах кнопки отличаются, можно добавить виртуальные методы или использовать `Dictionary<string, Button>` для более гибкого управления.

